# generate_unit2_part6.py: Part 6 - Architectural Modeling (Sections 32 to 36)

def get_unit2_part6_sections():
    return [{'id': 'sec-32', 'number': '32', 'part': 'Part 6 — Architectural Modeling', 'title': 'Architectural Modeling', 'subtitle': 'System Blueprint, Physical Architecture, Structural + Behavioral Integration', 'content': '\n<div class="topic-grid">\n  <div class="card overview-card">\n    <div class="card-badge">System Blueprint</div>\n    <h3>Meaning of Architectural Modeling</h3>\n    <p><strong>Architectural Modeling</strong> represents the <strong>overall high-level framework and physical blueprint of a software system</strong>. It integrates structural building blocks with dynamic runtime processes and maps them directly onto physical execution environments, hardware topologies, and network protocols.</p>\n  </div>\n</div>\n\n\n<div class="analogy-card">\n  <div class="analogy-header">💡 Real-Life Analogy: Kruchten\'s 4+1 Views of a Nuclear Power Plant</div>\n  <p>Building a nuclear power station requires multiple specialized engineering perspectives so that no single catastrophic mistake is made. The mechanical engineer consults the <strong>Implementation View</strong> (pipe specifications and valve alloys). The physicist consults the <strong>Logical View</strong> (neutron balance equations and safety state classes). The safety supervisor consults the <strong>Process View</strong> (cooling pump concurrency and alarm worker threads). The construction contractor consults the <strong>Deployment View</strong> (reinforced concrete containment domes and backup diesel generators). Kruchten\'s <strong>4+1 Architectural View Model</strong> ties all these distinct perspectives together around realistic end-user <strong>Use Case Scenarios</strong>.</p>\n</div>\n\n<div class="subtopics-container">\n  <h4>Core Perspectives of Architectural Modeling</h4>\n\n  <div class="detail-block">\n    <h5>1. The System Blueprint</h5>\n    <p>Architecture answers high-level non-functional questions that logical class diagrams cannot address:</p>\n    <ul>\n      <li><em>How is the software packaged into deliverable executables, libraries, and microservices?</em></li>\n      <li><em>Where do these binaries physically reside at runtime across client machines, application clusters, and cloud databases?</em></li>\n      <li><em>What communication protocols (HTTPS, gRPC, TCP/IP, JDBC) bridge the nodes?</em></li>\n    </ul>\n  </div>\n\n  <div class="detail-block">\n    <h5>2. The Two Core Architectural Diagrams</h5>\n    <div class="two-col-cards">\n      <div class="feature-card">\n        <div class="col-head blue-head">1. Component Diagram (Software View)</div>\n        <p>Models the <strong>static implementation view</strong>. Shows software artifacts, executables, source files, shared libraries (.dll, .so, .jar), and the interfaces through which they wire together.</p>\n      </div>\n\n      <div class="feature-card">\n        <div class="col-head green-head">2. Deployment Diagram (Hardware View)</div>\n        <p>Models the <strong>runtime physical architecture</strong>. Shows physical processing nodes (servers, edge devices, virtual machines) and the network connections linking them, with software components deployed inside.</p>\n      </div>\n    </div>\n  </div>\n</div>\n\n\n<div class="code-example-card">\n  <div class="code-header">\n    <span class="code-lang">C++ (Architectural 4+1 View Implementation)</span>\n    <span class="code-desc">Demonstrating how a single enterprise entity manifests across Logical, Process, and Deployment layers</span>\n  </div>\n  <pre class="code-block"><code><span class="c-keyword">#include</span> <span class="c-string">&lt;iostream&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;string&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;thread&gt;</span>\n\n<span class="c-comment">/* 1. LOGICAL VIEW: Domain Class Model */</span>\n<span class="c-keyword">class</span> <span class="c-type">PowerTelemetry</span> {\n<span class="c-keyword">public</span>:\n    <span class="c-type">double</span> megawattsOutput;\n    <span class="c-type">double</span> coreTemp;\n    <span class="c-type">PowerTelemetry</span>(<span class="c-type">double</span> mw, <span class="c-type">double</span> t) : megawattsOutput(mw), coreTemp(t) {}\n};\n\n<span class="c-comment">/* 2. PROCESS VIEW: Concurrency &amp; Worker Threads */</span>\n<span class="c-keyword">class</span> <span class="c-type">TelemetryWorker</span> {\n<span class="c-keyword">public</span>:\n    <span class="c-type">void</span> streamTelemetry(<span class="c-type">PowerTelemetry</span> data) {\n        <span class="c-type">std::thread</span> backgroundWorker([data]() {\n            <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"  [PROCESS VIEW] Worker Thread ID "</span> &lt;&lt; std::this_thread::get_id() \n                      &lt;&lt; <span class="c-string">" streaming output: "</span> &lt;&lt; data.megawattsOutput &lt;&lt; <span class="c-string">" MW"</span> &lt;&lt; <span class="c-type">std::endl</span>;\n        });\n        backgroundWorker.join();\n    }\n};\n\n<span class="c-comment">/* 3. DEPLOYMENT VIEW: Physical Infrastructure Node */</span>\n<span class="c-keyword">class</span> <span class="c-type">SCADANetworkNode</span> {\n<span class="c-keyword">private</span>:\n    <span class="c-type">std::string</span> ipAddress;\n    <span class="c-type">int</span> port;\n<span class="c-keyword">public</span>:\n    <span class="c-type">SCADANetworkNode</span>(<span class="c-type">std::string</span> ip, <span class="c-type">int</span> p) : ipAddress(ip), port(p) {}\n\n    <span class="c-type">void</span> sendPacket(<span class="c-keyword">const</span> <span class="c-type">PowerTelemetry</span>&amp; data) {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"[DEPLOYMENT VIEW] Packet transmitted to Node ["</span> \n                  &lt;&lt; ipAddress &lt;&lt; <span class="c-string">":"</span> &lt;&lt; port &lt;&lt; <span class="c-string">"] over TCP/IP protocol."</span> &lt;&lt; <span class="c-type">std::endl</span>;\n    }\n};\n\n<span class="c-type">int</span> main() {\n    <span class="c-type">PowerTelemetry</span> status(<span class="c-number">1200.5</span>, <span class="c-number">310.2</span>); <span class="c-comment">// Logical</span>\n    <span class="c-type">TelemetryWorker</span> worker;               <span class="c-comment">// Process</span>\n    <span class="c-type">SCADANetworkNode</span> controlTower(<span class="c-string">"192.168.1.50"</span>, <span class="c-number">8080</span>); <span class="c-comment">// Deployment</span>\n\n    worker.streamTelemetry(status);\n    controlTower.sendPacket(status);\n    <span class="c-keyword">return</span> <span class="c-number">0</span>;\n}</code></pre>\n</div>\n\n<div class="diagram-container">\n  <h4>Visual Model: Bridging Software Components to Physical Hardware Nodes</h4>\n  <div class="svg-diagram">\n    <svg viewBox="0 0 760 210" width="100%" height="210" xmlns="http://www.w3.org/2000/svg">\n      <defs>\n        <marker id="archArr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto">\n          <path d="M 0 1 L 10 5 L 0 9 z" fill="#8b5cf6"/>\n        </marker>\n      </defs>\n\n      <!-- Left: Software Component (Logical/Binary) -->\n      <g transform="translate(60, 40)">\n        <rect width="240" height="130" rx="4" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="2"/>\n        <rect x="-12" y="25" width="24" height="18" rx="2" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="1.8"/>\n        <rect x="-12" y="65" width="24" height="18" rx="2" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="1.8"/>\n        <text x="120" y="45" text-anchor="middle" font-size="11" fill="#2563eb">&lt;&lt;component&gt;&gt;</text>\n        <text x="120" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="var(--text-primary)">BillingEngine.jar</text>\n        <text x="120" y="95" text-anchor="middle" font-size="10" fill="var(--text-muted)">Packaged Software Module</text>\n      </g>\n\n      <!-- Mapping Arrow: Deployed Onto -->\n      <line x1="310" y1="105" x2="430" y2="105" stroke="#8b5cf6" stroke-width="2.5" stroke-dasharray="5,4" marker-end="url(#archArr)"/>\n      <text x="370" y="95" text-anchor="middle" font-size="10" font-weight="bold" fill="#7c3aed">&lt;&lt;deployed on&gt;&gt;</text>\n\n      <!-- Right: Hardware 3D Node (Physical) -->\n      <g transform="translate(440, 30)">\n        <!-- 3D Node Box -->\n        <polygon points="0,20 20,0 260,0 240,20" class="uml-activation" fill="rgba(56,189,248,0.25)" stroke="#38bdf8" stroke-width="1.5"/>\n        <polygon points="240,20 260,0 260,130 240,150" class="uml-cube-side" fill="#182335" stroke="#475569" stroke-width="1.5"/>\n        <rect x="0" y="20" width="240" height="130" fill="var(--card-bg)" stroke="#475569" stroke-width="2"/>\n        <text x="120" y="45" text-anchor="middle" font-size="11" fill="#059669">&lt;&lt;device&gt;&gt;</text>\n        <text x="120" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="var(--text-primary)">AppServerNode</text>\n        <rect x="25" y="80" width="190" height="50" rx="4" fill="rgba(99, 102, 241, 0.2)" stroke="#3b82f6"/>\n        <text x="120" y="110" text-anchor="middle" font-size="10" font-weight="bold" fill="#2563eb">Artifact: BillingEngine.jar</text>\n      </g>\n    </svg>\n  </div>\n</div>\n\n<div class="exam-corner">\n  <div class="exam-title">🎓 University Exam Corner (AKTU Reference)</div>\n  <p><strong>PYQ (AKTU 2012-13, 2014-15):</strong> <em>"What do you understand by architectural modeling? Name the main diagrams used in architectural modeling."</em> [5 Marks]</p>\n  <div class="tip-box">\n    <strong>Key Tip:</strong> Clearly emphasize that architectural modeling integrates structural and behavioral models to produce the physical blueprint of the system via <strong>Component Diagrams</strong> and <strong>Deployment Diagrams</strong>.\n  </div>\n</div>\n\n\n'}, {'id': 'sec-33', 'number': '33', 'part': 'Part 6 — Architectural Modeling', 'title': 'Component', 'subtitle': 'Modular Units, Replaceability, Implementation Packaging & System Evolution', 'content': '\n<div class="topic-grid">\n  <div class="card overview-card">\n    <div class="card-badge">Modular Unit</div>\n    <h3>Meaning of Component</h3>\n    <p>A <strong>Component</strong> is a modular, deployable, and replaceable part of a software system that encapsulates implementation details and exposes a set of external interfaces. It is a physical packaging of logical elements.</p>\n  </div>\n</div>\n\n\n<div class="analogy-card">\n  <div class="analogy-header">💡 Real-Life Analogy: Modular Computer Graphics Card (GPU) in a PCIe Slot</div>\n  <p>A software <strong>Component</strong> is like a modular graphics card (GPU). It is an autonomous, replaceable physical unit of packaging with clean boundaries. Whether the card is manufactured by NVIDIA or AMD, you can snap it into standard PCIe motherboard slots. The motherboard does not need to know whether the internal GPU chip uses 4,000 or 8,000 silicon cores; it only communicates through the standard hardware interface. In software, components are packaged as DLLs, shared libraries (`.so`), or JAR files that can be swapped without recompiling the host application.</p>\n</div>\n\n<div class="subtopics-container">\n  <h4>Key Characteristics and Packaging</h4>\n\n  <div class="detail-block">\n    <h5>1. The 3 Core Tenets of a Component</h5>\n    <ul>\n      <li><strong>Modular & Encapsulated:</strong> Hides internal source code behind strict interface boundaries.</li>\n      <li><strong>Deployable:</strong> Exists as an autonomous physical packaging (e.g. <code>.jar</code>, <code>.dll</code>, <code>.exe</code>, Docker container, or shared library).</li>\n      <li><strong>Replaceable (Plug-and-Play):</strong> Can be hot-swapped or upgraded with an alternative component provided both honor the same interface contracts.</li>\n    </ul>\n  </div>\n\n  <div class="detail-block">\n    <h5>2. Reusability and System Evolution</h5>\n    <p>Components form the foundation of <strong>Component-Based Software Engineering (CBSE)</strong>. Systems evolve by upgrading individual components without re-architecting the entire enterprise application.</p>\n  </div>\n</div>\n\n\n<div class="code-example-card">\n  <div class="code-header">\n    <span class="code-lang">C++ (Component Packaging with Facade & PIMPL Idiom)</span>\n    <span class="code-desc">Implementing an autonomous, replaceable component hiding internal complexity behind an export facade</span>\n  </div>\n  <pre class="code-block"><code><span class="c-keyword">#include</span> <span class="c-string">&lt;iostream&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;memory&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;string&gt;</span>\n\n<span class="c-comment">/* COMPONENT BOUNDARY: EncryptedPaymentComponent */</span>\n\n<span class="c-comment">// Internal implementation hidden from external consumers</span>\n<span class="c-keyword">class</span> <span class="c-type">PaymentEngineInternal</span> {\n<span class="c-keyword">public</span>:\n    <span class="c-type">bool</span> executeCardDeduction(<span class="c-type">std::string</span> card, <span class="c-type">double</span> amount) {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"  [COMPONENT INTERNAL] RSA-2048 encryption applied to card "</span> &lt;&lt; card &lt;&lt; <span class="c-type">std::endl</span>;\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"  [COMPONENT INTERNAL] Bank ISO-8583 message transmitted: ₹"</span> &lt;&lt; amount &lt;&lt; <span class="c-type">std::endl</span>;\n        <span class="c-keyword">return</span> <span class="c-keyword">true</span>;\n    }\n};\n\n<span class="c-comment">// Exported Public Component Facade</span>\n<span class="c-keyword">class</span> <span class="c-type">PaymentComponent</span> {\n<span class="c-keyword">private</span>:\n    <span class="c-type">std::unique_ptr</span>&lt;<span class="c-type">PaymentEngineInternal</span>&gt; pimpl; <span class="c-comment">// Pointer to Implementation</span>\n\n<span class="c-keyword">public</span>:\n    <span class="c-type">PaymentComponent</span>() : pimpl(<span class="c-type">std::make_unique</span>&lt;<span class="c-type">PaymentEngineInternal</span>&gt;()) {}\n\n    <span class="c-comment">// Public Component API Port</span>\n    <span class="c-type">bool</span> pay(<span class="c-type">std::string</span> cardNumber, <span class="c-type">double</span> amount) {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"[COMPONENT FACADE] Received payment request at component port."</span> &lt;&lt; <span class="c-type">std::endl</span>;\n        <span class="c-keyword">return</span> pimpl-&gt;executeCardDeduction(cardNumber, amount);\n    }\n};\n\n<span class="c-type">int</span> main() {\n    <span class="c-comment">// Client application utilizes the component as a black-box</span>\n    <span class="c-type">PaymentComponent</span> paymentModule;\n    <span class="c-type">bool</span> status = paymentModule.pay(<span class="c-string">"4532-XXXX-XXXX-9012"</span>, <span class="c-number">2499.0</span>);\n    <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"Component Payment Status: "</span> &lt;&lt; (status ? <span class="c-string">"SUCCESS"</span> : <span class="c-string">"FAILURE"</span>) &lt;&lt; <span class="c-type">std::endl</span>;\n    <span class="c-keyword">return</span> <span class="c-number">0</span>;\n}</code></pre>\n</div>\n\n<div class="diagram-container">\n  <h4>Visual Model: Standard UML Component Notations</h4>\n  <div class="svg-diagram">\n    <svg viewBox="0 0 760 180" width="100%" height="180" xmlns="http://www.w3.org/2000/svg">\n      <!-- UML 1.x Classic Tabbed Notation -->\n      <g transform="translate(80, 25)">\n        <rect width="240" height="120" rx="4" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="2"/>\n        <rect x="-14" y="25" width="28" height="20" rx="2" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="1.8"/>\n        <rect x="-14" y="65" width="28" height="20" rx="2" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="1.8"/>\n        <text x="120" y="55" text-anchor="middle" font-size="11" fill="#2563eb">&lt;&lt;component&gt;&gt;</text>\n        <text x="120" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="var(--text-primary)">AuthService.dll</text>\n        <text x="120" y="110" text-anchor="middle" font-size="10" fill="var(--text-muted)">Classic UML Component Icon</text>\n      </g>\n\n      <!-- UML 2.x Modern Notational Variant -->\n      <g transform="translate(420, 25)">\n        <rect width="240" height="120" rx="4" fill="var(--card-bg)" stroke="#10b981" stroke-width="2"/>\n        <!-- Mini component icon in top right -->\n        <rect x="200" y="12" width="24" height="16" rx="2" fill="none" stroke="#10b981" stroke-width="1.5"/>\n        <rect x="196" y="15" width="8" height="4" fill="var(--card-bg)" stroke="#10b981"/>\n        <rect x="196" y="21" width="8" height="4" fill="var(--card-bg)" stroke="#10b981"/>\n        <text x="120" y="55" text-anchor="middle" font-size="11" fill="#059669">&lt;&lt;component&gt;&gt;</text>\n        <text x="120" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="var(--text-primary)">PaymentProcessor</text>\n        <text x="120" y="110" text-anchor="middle" font-size="10" fill="var(--text-muted)">Modern UML 2.x Box with Tag</text>\n      </g>\n    </svg>\n  </div>\n</div>\n\n<div class="exam-corner">\n  <div class="exam-title">🎓 University Exam Corner (AKTU Reference)</div>\n  <p><strong>PYQ:</strong> <em>"Define a component. What do you mean by a replaceable part of a system?"</em> [5 Marks]</p>\n  <div class="tip-box">\n    <strong>Key Scoring Points:</strong> Explain that a component is a physical, deployable, and replaceable unit. It can be replaced at runtime or compile-time without affecting clients, as long as interface contracts are maintained.\n  </div>\n</div>\n\n\n'}, {'id': 'sec-34', 'number': '34', 'part': 'Part 6 — Architectural Modeling', 'title': 'Interface', 'subtitle': 'Operation Collections, Provided vs Required, Ball-and-Socket & Realization', 'content': '\n<div class="topic-grid">\n  <div class="card overview-card">\n    <div class="card-badge">Contract Specification</div>\n    <h3>Meaning of Interface</h3>\n    <p>An <strong>Interface</strong> is a named collection of operations that specifies a contract for the services offered by a class or component without dictating its internal implementation. It enforces the <em>Separation of Interface and Implementation</em>.</p>\n  </div>\n</div>\n\n\n<div class="analogy-card">\n  <div class="analogy-header">💡 Real-Life Analogy: Universal Wall Plug Socket & Appliance Cord</div>\n  <p>An <strong>Interface</strong> is represented in UML by the famous \'Ball-and-Socket\' notation. The 3-pin wall electrical socket is the <strong>Provided Interface (\'O—\' Lollipop)</strong>: it promises to provide 230V AC current according to a standard spec. The laptop charger plug is the <strong>Required Interface (\')—\' Socket)</strong>: it requires 230V AC to function. The electrical grid doesn\'t care whether the plugged device is a toaster, television, or Tesla charger—as long as the appliance realizes the required interface, complete decoupling is achieved!</p>\n</div>\n\n<div class="subtopics-container">\n  <h4>The Two Notational Conventions in UML</h4>\n\n  <div class="detail-block">\n    <h5>1. Provided vs. Required Interfaces (Ball-and-Socket / Lollipop Notation)</h5>\n    <ul>\n      <li><strong>Provided Interface (Lollipop / Ball <code>—○</code>):</strong> A service that the component implements and offers to other components.</li>\n      <li><strong>Required Interface (Socket / Cup <code>—)</code>):</strong> A service that the component expects or requires from external entities to function.</li>\n      <li><strong>Assembly Connector:</strong> When a provided lollipop fits into a required socket, forming a complete plug-and-play connection!</li>\n    </ul>\n  </div>\n\n  <div class="detail-block">\n    <h5>2. Stereotyped Classifier Notation</h5>\n    <p>A standard rectangle adorned with <code>&lt;&lt;interface&gt;&gt;</code> listing the abstract operations. Classes and components realize this interface using a <strong>dashed line with a hollow triangle (<code>- - -▷</code>)</strong>.</p>\n  </div>\n</div>\n\n\n<div class="code-example-card">\n  <div class="code-header">\n    <span class="code-lang">C++ (Provided vs Required Interfaces & Dependency Injection)</span>\n    <span class="code-desc">Demonstrating pure virtual interfaces realizing loose coupling and dependency injection</span>\n  </div>\n  <pre class="code-block"><code><span class="c-keyword">#include</span> <span class="c-string">&lt;iostream&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;string&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;memory&gt;</span>\n\n/* \n * PROVIDED INTERFACE (<span class="c-type">Lollipop</span> \'O-\'): <span class="c-type">ILogger</span>\n * A contract defining operations without implementation.\n */\n<span class="c-keyword">class</span> <span class="c-type">ILogger</span> {\n<span class="c-keyword">public</span>:\n    <span class="c-keyword">virtual</span> ~<span class="c-type">ILogger</span>() = <span class="c-keyword">default</span>;\n    <span class="c-keyword">virtual</span> <span class="c-type">void</span> log(<span class="c-keyword">const</span> <span class="c-type">std::string</span>&amp; message) = <span class="c-number">0</span>; <span class="c-comment">// Pure virtual method</span>\n};\n\n<span class="c-comment">/* Realization: Component A provides the interface */</span>\n<span class="c-keyword">class</span> <span class="c-type">CloudLogger</span> : <span class="c-keyword">public</span> <span class="c-type">ILogger</span> {\n<span class="c-keyword">public</span>:\n    <span class="c-type">void</span> log(<span class="c-keyword">const</span> <span class="c-type">std::string</span>&amp; message) <span class="c-keyword">override</span> {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"  [Provided Interface Realization] CloudLogger sending log: "</span> &lt;&lt; message &lt;&lt; <span class="c-type">std::endl</span>;\n    }\n};\n\n/* \n * REQUIRED INTERFACE (<span class="c-type">Socket</span> \')-(\'):\n * <span class="c-type">UserService</span> requires any <span class="c-type">ILogger</span> implementation via its port.\n */\n<span class="c-keyword">class</span> <span class="c-type">UserService</span> {\n<span class="c-keyword">private</span>:\n    <span class="c-type">std::shared_ptr</span>&lt;<span class="c-type">ILogger</span>&gt; loggerPort; <span class="c-comment">// Required Interface dependency</span>\n\n<span class="c-keyword">public</span>:\n    <span class="c-comment">// Dependency Injection wiring the Provided interface to Required interface</span>\n    <span class="c-type">UserService</span>(<span class="c-type">std::shared_ptr</span>&lt;<span class="c-type">ILogger</span>&gt; logger) : loggerPort(logger) {}\n\n    <span class="c-type">void</span> registerUser(<span class="c-type">std::string</span> username) {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"UserService: Registering "</span> &lt;&lt; username &lt;&lt; <span class="c-string">"..."</span> &lt;&lt; <span class="c-type">std::endl</span>;\n        loggerPort-&gt;log(<span class="c-string">"User "</span> + username + <span class="c-string">" successfully enrolled in system."</span>);\n    }\n};\n\n<span class="c-type">int</span> main() {\n    <span class="c-comment">// Wiring the assembly connector at runtime</span>\n    <span class="c-keyword">auto</span> cloudLog = <span class="c-type">std::make_shared</span>&lt;<span class="c-type">CloudLogger</span>&gt;();\n    <span class="c-type">UserService</span> service(cloudLog);\n\n    service.registerUser(<span class="c-string">"shubham_upes"</span>);\n    <span class="c-keyword">return</span> <span class="c-number">0</span>;\n}</code></pre>\n</div>\n\n<div class="diagram-container">\n  <h4>Visual Model: Ball-and-Socket Assembly Connector & Realization</h4>\n  <div class="svg-diagram">\n    <svg viewBox="0 0 760 210" width="100%" height="210" xmlns="http://www.w3.org/2000/svg">\n      <!-- Component A (Provider) -->\n      <g transform="translate(60, 40)">\n        <rect width="180" height="90" rx="4" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="2"/>\n        <text x="90" y="45" text-anchor="middle" font-size="11" fill="#2563eb">&lt;&lt;component&gt;&gt;</text>\n        <text x="90" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="var(--text-primary)">DatabaseService</text>\n        <!-- Lollipop (Ball) extending right -->\n        <line x1="180" y1="50" x2="260" y2="50" stroke="#3b82f6" stroke-width="2"/>\n        <circle cx="270" cy="50" r="10" fill="#3b82f6" stroke="#1d4ed8" stroke-width="2"/>\n      </g>\n      <text x="325" y="35" text-anchor="middle" font-size="10" font-weight="bold" fill="#2563eb">Provided: IDatabase</text>\n\n      <!-- Assembly Joint in Center -->\n      <!-- Component B (Consumer) with Socket -->\n      <g transform="translate(420, 40)">\n        <!-- Socket (Cup) extending left to meet Ball -->\n        <path d="M -70 38 A 14 14 0 0 0 -70 62" fill="none" stroke="#10b981" stroke-width="2.5"/>\n        <line x1="-70" y1="50" x2="0" y2="50" stroke="#10b981" stroke-width="2"/>\n        \n        <rect width="180" height="90" rx="4" fill="var(--card-bg)" stroke="#10b981" stroke-width="2"/>\n        <text x="90" y="45" text-anchor="middle" font-size="11" fill="#059669">&lt;&lt;component&gt;&gt;</text>\n        <text x="90" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="var(--text-primary)">BillingClient</text>\n      </g>\n      <text x="385" y="75" text-anchor="middle" font-size="10" font-weight="bold" fill="#059669">Required: IDatabase</text>\n\n      <text x="370" y="165" text-anchor="middle" font-size="11" fill="var(--text-muted)">Ball (Provided) snaps into Socket (Required) forming an Assembly Connector.</text>\n    </svg>\n  </div>\n</div>\n\n<div class="exam-corner">\n  <div class="exam-title">🎓 University Exam Corner (AKTU Reference)</div>\n  <p><strong>PYQ:</strong> <em>"What is an interface? Explain lollipop (ball-and-socket) notation and interface realization."</em> [5 Marks]</p>\n  <div class="tip-box">\n    <strong>Exam Must-Draw:</strong> Draw both the lollipop (provided) circle and the socket (required) semicircle. Show how they connect together to form an assembly connector.\n  </div>\n</div>\n\n\n'}, {'id': 'sec-35', 'number': '35', 'part': 'Part 6 — Architectural Modeling', 'title': 'Component Diagram', 'subtitle': 'Static Implementation View, Software Artifacts, Executables & Component Dependencies', 'content': '\n<div class="topic-grid">\n  <div class="card overview-card">\n    <div class="card-badge">Implementation Architecture</div>\n    <h3>Meaning and Purpose of Component Diagrams</h3>\n    <p>A <strong>Component Diagram</strong> illustrates the <strong>static implementation view</strong> of a system. It visualizes how source code files, binaries, libraries, executables, scripts, and database tables are organized into deployable software components and how they depend on each other via interfaces.</p>\n  </div>\n</div>\n\n\n<div class="analogy-card">\n  <div class="analogy-header">💡 Real-Life Analogy: Hi-Fi Stereo System Wiring & Assembly Connectors</div>\n  <p>A <strong>Component Diagram</strong> models the physical wiring and assembly connectors between software components. Imagine assembling a luxury home theater: the Blu-Ray Player component provides an \'Audio-Out\' port; the Surround Sound Amplifier component requires an \'Audio-In\' port and provides an amplified \'Speaker-Out\' port; the Subwoofer component requires a \'Speaker-In\' port. Connecting an HDMI cable between these ports is an <strong>Assembly Connector</strong>. The diagram visualizes the modular architecture of the entire audio system.</p>\n</div>\n\n<div class="subtopics-container">\n  <h4>Architectural Components and Adaptability</h4>\n\n  <div class="detail-block">\n    <h5>1. Core Elements of Component Diagrams</h5>\n    <ul>\n      <li><strong>Components:</strong> Modular code/executable blocks (e.g. <code>UI.war</code>, <code>OrderService.jar</code>, <code>InventoryDB</code>).</li>\n      <li><strong>Provided & Required Interfaces:</strong> The contracts governing communication.</li>\n      <li><strong>Dependencies (<code>- - - -></code>):</strong> Indicates that one component relies on another component or interface.</li>\n      <li><strong>Artifacts:</strong> Physical manifest files (e.g. <code>config.xml</code>, <code>app.exe</code>).</li>\n    </ul>\n  </div>\n\n  <div class="detail-block">\n    <h5>2. Adaptable Systems & Component-Based Software Engineering (CBSE)</h5>\n    <p>Component diagrams enable architects to model adaptable, loosely-coupled systems. When business rules change, only the affected component is updated and swapped without recompiling the entire system.</p>\n  </div>\n</div>\n\n\n<div class="code-example-card">\n  <div class="code-header">\n    <span class="code-lang">C++ (Component Assembly Connectors & Wiring Ports)</span>\n    <span class="code-desc">Wiring decoupled components together using port delegates and assembly connectors</span>\n  </div>\n  <pre class="code-block"><code><span class="c-keyword">#include</span> <span class="c-string">&lt;iostream&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;string&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;memory&gt;</span>\n\n<span class="c-comment">// Port Interface 1: Audio Signal</span>\n<span class="c-keyword">class</span> <span class="c-type">IAudioOutputPort</span> {\n<span class="c-keyword">public</span>:\n    <span class="c-keyword">virtual</span> ~<span class="c-type">IAudioOutputPort</span>() = <span class="c-keyword">default</span>;\n    <span class="c-keyword">virtual</span> <span class="c-type">void</span> transmitAudio(<span class="c-type">std::string</span> audioStream) = <span class="c-number">0</span>;\n};\n\n<span class="c-comment">// Component 1: Media Player (Provides AudioOutputPort)</span>\n<span class="c-keyword">class</span> <span class="c-type">MediaPlayerComponent</span> : <span class="c-keyword">public</span> <span class="c-type">IAudioOutputPort</span> {\n<span class="c-keyword">public</span>:\n    <span class="c-type">void</span> transmitAudio(<span class="c-type">std::string</span> audioStream) <span class="c-keyword">override</span> {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"  [MediaPlayer Port] Transmitting audio stream: "</span> &lt;&lt; audioStream &lt;&lt; <span class="c-type">std::endl</span>;\n    }\n};\n\n<span class="c-comment">// Component 2: Sound Amplifier (Requires AudioOutputPort via Assembly Connector)</span>\n<span class="c-keyword">class</span> <span class="c-type">AmplifierComponent</span> {\n<span class="c-keyword">private</span>:\n    <span class="c-type">IAudioOutputPort</span>* inputConnector; <span class="c-comment">// Assembly connector hook</span>\n\n<span class="c-keyword">public</span>:\n    <span class="c-type">void</span> connectAudioSource(<span class="c-type">IAudioOutputPort</span>* source) {\n        inputConnector = source; <span class="c-comment">// Wiring the assembly connector</span>\n    }\n\n    <span class="c-type">void</span> amplifyAndPlay(<span class="c-type">std::string</span> track) {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"[Amplifier Component] Processing signal through equalizer..."</span> &lt;&lt; <span class="c-type">std::endl</span>;\n        <span class="c-keyword">if</span> (inputConnector) {\n            inputConnector-&gt;transmitAudio(track);\n            <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"[Amplifier Component] Outputting 100W surround sound to speakers!"</span> &lt;&lt; <span class="c-type">std::endl</span>;\n        }\n    }\n};\n\n<span class="c-type">int</span> main() {\n    <span class="c-type">MediaPlayerComponent</span> player;\n    <span class="c-type">AmplifierComponent</span> amp;\n\n    <span class="c-comment">// Assembly Connector: Wiring Component 1 to Component 2</span>\n    amp.connectAudioSource(&amp;player);\n    amp.amplifyAndPlay(<span class="c-string">"Beethoven Symphony No. 9"</span>);\n    <span class="c-keyword">return</span> <span class="c-number">0</span>;\n}</code></pre>\n</div>\n\n<div class="diagram-container">\n  <h4>Visual Model: Enterprise E-Commerce Component Diagram</h4>\n  <div class="svg-diagram">\n    <svg viewBox="0 0 760 250" width="100%" height="250" xmlns="http://www.w3.org/2000/svg">\n      <defs>\n        <marker id="compDep" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto">\n          <path d="M 0 1 L 10 5 L 0 9" fill="none" stroke="#2563eb" stroke-width="1.8"/>\n        </marker>\n      </defs>\n\n      <!-- Component 1: Web Frontend -->\n      <g transform="translate(40, 75)">\n        <rect width="180" height="90" rx="4" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="2"/>\n        <rect x="-10" y="20" width="20" height="15" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="1.5"/>\n        <rect x="-10" y="55" width="20" height="15" fill="var(--card-bg)" stroke="#3b82f6" stroke-width="1.5"/>\n        <text x="90" y="42" text-anchor="middle" font-size="10" fill="#2563eb">&lt;&lt;component&gt;&gt;</text>\n        <text x="90" y="62" text-anchor="middle" font-size="12" font-weight="bold" fill="var(--text-primary)">WebClient.war</text>\n      </g>\n\n      <!-- Dependency 1 -->\n      <line x1="220" y1="120" x2="295" y2="120" stroke="#2563eb" stroke-width="2" stroke-dasharray="4,4" marker-end="url(#compDep)"/>\n      <text x="255" y="110" text-anchor="middle" font-size="9" font-weight="bold" fill="#2563eb">&lt;&lt;use&gt;&gt;</text>\n\n      <!-- Component 2: Business Order Service -->\n      <g transform="translate(300, 75)">\n        <rect width="180" height="90" rx="4" fill="var(--card-bg)" stroke="#10b981" stroke-width="2"/>\n        <rect x="-10" y="20" width="20" height="15" fill="var(--card-bg)" stroke="#10b981" stroke-width="1.5"/>\n        <rect x="-10" y="55" width="20" height="15" fill="var(--card-bg)" stroke="#10b981" stroke-width="1.5"/>\n        <text x="90" y="42" text-anchor="middle" font-size="10" fill="#059669">&lt;&lt;component&gt;&gt;</text>\n        <text x="90" y="62" text-anchor="middle" font-size="12" font-weight="bold" fill="var(--text-primary)">OrderService.jar</text>\n      </g>\n\n      <!-- Dependency 2 -->\n      <line x1="480" y1="120" x2="555" y2="120" stroke="#2563eb" stroke-width="2" stroke-dasharray="4,4" marker-end="url(#compDep)"/>\n      <text x="515" y="110" text-anchor="middle" font-size="9" font-weight="bold" fill="#2563eb">&lt;&lt;use&gt;&gt;</text>\n\n      <!-- Component 3: Database Component -->\n      <g transform="translate(560, 75)">\n        <rect width="160" height="90" rx="4" fill="var(--card-bg)" stroke="#8b5cf6" stroke-width="2"/>\n        <rect x="-10" y="20" width="20" height="15" fill="var(--card-bg)" stroke="#8b5cf6" stroke-width="1.5"/>\n        <rect x="-10" y="55" width="20" height="15" fill="var(--card-bg)" stroke="#8b5cf6" stroke-width="1.5"/>\n        <text x="80" y="42" text-anchor="middle" font-size="10" fill="#7c3aed">&lt;&lt;database&gt;&gt;</text>\n        <text x="80" y="62" text-anchor="middle" font-size="12" font-weight="bold" fill="var(--text-primary)">PostgresDB</text>\n      </g>\n    </svg>\n  </div>\n</div>\n\n<div class="exam-corner">\n  <div class="exam-title">🎓 University Exam Corner (AKTU Reference)</div>\n  <p><strong>PYQ (AKTU 2010-11, 2015-16):</strong> <em>"Describe in brief component diagram. Draw a component diagram for an online shopping system."</em> [5 Marks]</p>\n  <div class="tip-box">\n    <strong>Key Scoring Points:</strong> Draw at least 3 components (Frontend, Service, Database). Use the standard tabbed box symbol and connect them using dashed dependency arrows.\n  </div>\n</div>\n\n\n'}, {'id': 'sec-36', 'number': '36', 'part': 'Part 6 — Architectural Modeling', 'title': 'Deployment Diagram', 'subtitle': 'Runtime Hardware Nodes, Communication Paths, Network Protocols & Nodes vs Components', 'content': '\n<div class="topic-grid">\n  <div class="card overview-card">\n    <div class="card-badge">Physical Architecture</div>\n    <h3>Meaning and Purpose of Deployment Diagrams</h3>\n    <p>A <strong>Deployment Diagram</strong> portrays the <strong>runtime physical architecture of a system</strong>. It shows the hardware configuration (nodes, servers, sensors, workstations), the network communication paths connecting them, and the concrete software artifacts deployed on those physical execution nodes.</p>\n  </div>\n</div>\n\n\n<div class="analogy-card">\n  <div class="analogy-header">💡 Real-Life Analogy: Global Banking Infrastructure: Server Nodes and ATM Kiosks</div>\n  <p>A <strong>Deployment Diagram</strong> represents the physical hardware topology where software artifacts actually run. In a nationwide bank, there is a central <strong>Mainframe Node</strong> in Mumbai housing high-capacity database servers. Connected via encrypted WAN communication links are thousands of <strong>ATM Kiosk Nodes</strong> distributed across cities, each running an embedded Windows/Linux OS and hosting a client artifact (`atm_client.exe`). The deployment diagram proves where code physically lives and verifies network latency, hardware capacity, and security firewalls.</p>\n</div>\n\n<div class="subtopics-container">\n  <h4>Key Terminology & Node vs. Component Distinction</h4>\n\n  <div class="detail-block">\n    <h5>1. Key Architectural Elements</h5>\n    <ul>\n      <li><strong>Node:</strong> A physical computational resource that possesses memory and processing power. Represented as a <strong>3D box (cube)</strong>.</li>\n      <li><strong>Device Node vs. Execution Environment Node:</strong> A physical hardware device (e.g., <code>&lt;&lt;device&gt;&gt; ApplicationServer</code>) vs an execution platform (e.g., <code>&lt;&lt;execution environment&gt;&gt; JVM</code> or <code>DockerEngine</code>).</li>\n      <li><strong>Communication Path:</strong> A solid line connecting nodes, stereotyped with network protocols (e.g. <code>&lt;&lt;TCP/IP&gt;&gt;</code>, <code>&lt;&lt;HTTPS&gt;&gt;</code>, <code>&lt;&lt;JDBC&gt;&gt;</code>).</li>\n      <li><strong>Deployed Artifact:</strong> The concrete software binary (e.g., <code>app.war</code>, <code>service.exe</code>) drawn inside the node cube.</li>\n    </ul>\n  </div>\n\n  <div class="detail-block">\n    <h5>2. Crucial Exam Comparison: Node vs. Component</h5>\n    <table class="styled-table">\n      <thead>\n        <tr>\n          <th>Criterion</th>\n          <th>Node (Deployment Diagram)</th>\n          <th>Component (Component Diagram)</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><strong>Nature</strong></td>\n          <td><strong>Hardware element</strong> or physical execution host</td>\n          <td><strong>Software element</strong> (executable, binary, code artifact)</td>\n        </tr>\n        <tr>\n          <td><strong>UML Notation</strong></td>\n          <td>3-Dimensional Box / Cube</td>\n          <td>Rectangle with two small protruding tabs on the left border</td>\n        </tr>\n        <tr>\n          <td><strong>Physical Existence</strong></td>\n          <td>Possesses memory, CPU, and physical spatial location</td>\n          <td>Resides <em>inside</em> a node; executes on the node\'s processor</td>\n        </tr>\n        <tr>\n          <td><strong>Examples</strong></td>\n          <td>Database Server, Smartphone, POS Terminal, Router</td>\n          <td><code>paymentService.jar</code>, <code>auth.dll</code>, <code>schema.sql</code></td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n\n<div class="code-example-card">\n  <div class="code-header">\n    <span class="code-lang">C++ (Deployment Node Client-Server Topology Simulation)</span>\n    <span class="code-desc">Demonstrating physical node topology, communication protocol, and artifact execution</span>\n  </div>\n  <pre class="code-block"><code><span class="c-keyword">#include</span> <span class="c-string">&lt;iostream&gt;</span>\n<span class="c-keyword">#include</span> <span class="c-string">&lt;string&gt;</span>\n\n<span class="c-comment">/* Hardware Node 1: Central Database Cluster Node (Mumbai DataCenter) */</span>\n<span class="c-keyword">class</span> <span class="c-type">CentralServerNode</span> {\n<span class="c-keyword">public</span>:\n    <span class="c-type">void</span> receiveTCPPayload(<span class="c-type">std::string</span> clientNodeIP, <span class="c-type">std::string</span> transactionPayload) {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"[SERVER NODE: 10.0.1.100 Mumbai] Received packet from "</span> \n                  &lt;&lt; clientNodeIP &lt;&lt; <span class="c-string">" over TLS/TCP: "</span> &lt;&lt; transactionPayload &lt;&lt; <span class="c-type">std::endl</span>;\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"  -&gt; Transaction committed to Oracle Database Cluster Artifact."</span> &lt;&lt; <span class="c-type">std::endl</span>;\n    }\n};\n\n<span class="c-comment">/* Hardware Node 2: Remote ATM Kiosk Node (Delhi Branch Device) */</span>\n<span class="c-keyword">class</span> <span class="c-type">ATMKioskDeviceNode</span> {\n<span class="c-keyword">private</span>:\n    <span class="c-type">std::string</span> deviceIP;\n    <span class="c-type">CentralServerNode</span>* serverLink; <span class="c-comment">// WAN Communication Path: &lt;&lt;TCP/IP&gt;&gt;</span>\n\n<span class="c-keyword">public</span>:\n    <span class="c-type">ATMKioskDeviceNode</span>(<span class="c-type">std::string</span> ip, <span class="c-type">CentralServerNode</span>* server) \n        : deviceIP(ip), serverLink(server) {}\n\n    <span class="c-comment">// Executing local artifact: atm_client.exe</span>\n    <span class="c-type">void</span> executeWithdrawal(<span class="c-type">std::string</span> account, <span class="c-type">double</span> amount) {\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"[CLIENT NODE: "</span> &lt;&lt; deviceIP &lt;&lt; <span class="c-string">" Delhi ATM] User card inserted."</span> &lt;&lt; <span class="c-type">std::endl</span>;\n        <span class="c-type">std::string</span> payload = <span class="c-string">"{acc: \'"</span> + account + <span class="c-string">"\', withdraw: "</span> + std::to_string(amount) + <span class="c-string">"}"</span>;\n        \n        <span class="c-comment">// Transmitting over communication path &lt;&lt;TCP/IP&gt;&gt;</span>\n        serverLink-&gt;receiveTCPPayload(deviceIP, payload);\n        <span class="c-type">std::cout</span> &lt;&lt; <span class="c-string">"[CLIENT NODE: "</span> &lt;&lt; deviceIP &lt;&lt; <span class="c-string">"] Cash dispensed physically to user."</span> &lt;&lt; <span class="c-type">std::endl</span>;\n    }\n};\n\n<span class="c-type">int</span> main() {\n    <span class="c-comment">// Deploying software artifacts to physical execution nodes</span>\n    <span class="c-type">CentralServerNode</span> mumbaiDatacenter;\n    <span class="c-type">ATMKioskDeviceNode</span> delhiKiosk(<span class="c-string">"172.16.42.10"</span>, &amp;mumbaiDatacenter);\n\n    delhiKiosk.executeWithdrawal(<span class="c-string">"ACC-904128"</span>, <span class="c-number">5000.0</span>);\n    <span class="c-keyword">return</span> <span class="c-number">0</span>;\n}</code></pre>\n</div>\n\n<div class="diagram-container">\n  <h4>Visual Model: 3-Tier Enterprise Cloud Deployment Diagram</h4>\n  <div class="svg-diagram">\n    <svg viewBox="0 0 760 270" width="100%" height="270" xmlns="http://www.w3.org/2000/svg">\n      <!-- Node 1: Client Machine -->\n      <g transform="translate(30, 70)">\n        <polygon points="0,15 15,0 170,0 155,15" class="uml-activation" fill="rgba(56,189,248,0.25)" stroke="#38bdf8" stroke-width="1.5"/>\n        <polygon points="155,15 170,0 170,105 155,120" class="uml-cube-side" fill="#182335" stroke="#475569" stroke-width="1.5"/>\n        <rect x="0" y="15" width="155" height="105" fill="var(--card-bg)" stroke="#475569" stroke-width="2"/>\n        <text x="77" y="38" text-anchor="middle" font-size="10" fill="#2563eb">&lt;&lt;device&gt;&gt;</text>\n        <text x="77" y="55" text-anchor="middle" font-size="11" font-weight="bold" fill="var(--text-primary)">Client Browser</text>\n        <rect x="15" y="68" width="125" height="40" rx="3" fill="rgba(99, 102, 241, 0.2)" stroke="#3b82f6"/>\n        <text x="77" y="92" text-anchor="middle" font-size="9" font-weight="bold" fill="#2563eb">&lt;&lt;artifact&gt;&gt; SPA.js</text>\n      </g>\n\n      <!-- Communication Path 1 -->\n      <line x1="185" y1="130" x2="285" y2="130" stroke="#64748b" stroke-width="2"/>\n      <text x="235" y="120" text-anchor="middle" font-size="9" font-weight="bold" fill="#2563eb">&lt;&lt;HTTPS&gt;&gt;</text>\n\n      <!-- Node 2: App Server -->\n      <g transform="translate(285, 50)">\n        <polygon points="0,15 15,0 185,0 170,15" class="uml-activation" fill="rgba(56,189,248,0.25)" stroke="#38bdf8" stroke-width="1.5"/>\n        <polygon points="170,15 185,0 185,125 170,140" class="uml-cube-side" fill="#182335" stroke="#475569" stroke-width="1.5"/>\n        <rect x="0" y="15" width="170" height="125" fill="var(--card-bg)" stroke="#475569" stroke-width="2"/>\n        <text x="85" y="38" text-anchor="middle" font-size="10" fill="#059669">&lt;&lt;device&gt;&gt;</text>\n        <text x="85" y="55" text-anchor="middle" font-size="11" font-weight="bold" fill="var(--text-primary)">App Server</text>\n        <rect x="15" y="68" width="140" height="55" rx="3" fill="rgba(16, 185, 129, 0.2)" stroke="#10b981"/>\n        <text x="85" y="88" text-anchor="middle" font-size="9" font-weight="bold" fill="#059669">&lt;&lt;artifact&gt;&gt; ApiServer.jar</text>\n        <text x="85" y="105" text-anchor="middle" font-size="8" fill="var(--text-muted)">Running in JVM</text>\n      </g>\n\n      <!-- Communication Path 2 -->\n      <line x1="455" y1="130" x2="550" y2="130" stroke="#64748b" stroke-width="2"/>\n      <text x="502" y="120" text-anchor="middle" font-size="9" font-weight="bold" fill="#7c3aed">&lt;&lt;JDBC/SSL&gt;&gt;</text>\n\n      <!-- Node 3: DB Server -->\n      <g transform="translate(550, 70)">\n        <polygon points="0,15 15,0 170,0 155,15" class="uml-activation" fill="rgba(56,189,248,0.25)" stroke="#38bdf8" stroke-width="1.5"/>\n        <polygon points="155,15 170,0 170,105 155,120" class="uml-cube-side" fill="#182335" stroke="#475569" stroke-width="1.5"/>\n        <rect x="0" y="15" width="155" height="105" fill="var(--card-bg)" stroke="#475569" stroke-width="2"/>\n        <text x="77" y="38" text-anchor="middle" font-size="10" fill="#7c3aed">&lt;&lt;device&gt;&gt;</text>\n        <text x="77" y="55" text-anchor="middle" font-size="11" font-weight="bold" fill="var(--text-primary)">Database Cluster</text>\n        <rect x="15" y="68" width="125" height="40" rx="3" fill="rgba(139, 92, 246, 0.2)" stroke="#8b5cf6"/>\n        <text x="77" y="92" text-anchor="middle" font-size="9" font-weight="bold" fill="#7c3aed">&lt;&lt;artifact&gt;&gt; data.db</text>\n      </g>\n    </svg>\n  </div>\n</div>\n\n<div class="exam-corner">\n  <div class="exam-title">🎓 University Exam Corner (AKTU Reference)</div>\n  <p><strong>PYQ (AKTU 2014-15):</strong> <em>"Explain deployment diagrams with a suitable diagram. What is the difference between components and nodes?"</em> [10 Marks]</p>\n  <div class="tip-box">\n    <strong>Key Marking Formula:</strong> Draw the 3D cube nodes with communication path protocols (e.g. <code>&lt;&lt;TCP/IP&gt;&gt;</code>, <code>&lt;&lt;HTTPS&gt;&gt;</code>). Provide the Node vs Component comparison table given above for full marks.\n  </div>\n</div>\n\n\n'}]
